package com.example.jobfinderapp.activities;
import android.content.Intent; import android.os.Bundle; import android.os.Handler; import android.os.Looper; import android.view.animation.AnimationUtils; import androidx.appcompat.app.AppCompatActivity; import com.example.jobfinderapp.R; import com.example.jobfinderapp.database.DBHelper; import com.example.jobfinderapp.models.User; import com.example.jobfinderapp.utils.UserSession;
public class SplashActivity extends AppCompatActivity {
 private DBHelper db; private UserSession session;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_splash);db=DBHelper.getInstance(this);session=new UserSession(this);findViewById(R.id.ivSplashLogo).startAnimation(AnimationUtils.loadAnimation(this,R.anim.logo_scale_fade));findViewById(R.id.layoutSplashText).startAnimation(AnimationUtils.loadAnimation(this,R.anim.text_fade_up));new Handler(Looper.getMainLooper()).postDelayed(this::route,1100);}
 private void route(){User u=session.isLoggedIn()?db.getUserById(session.getUserId()):null;Class<?> target=LoginActivity.class;if(u!=null&&DBHelper.STATUS_ACTIVE.equals(u.getStatus())){if(DBHelper.ROLE_CANDIDATE.equals(u.getRole()))target=HomeActivity.class;else if(DBHelper.ROLE_EMPLOYER.equals(u.getRole()))target=EmployerDashboardActivity.class;else if(DBHelper.ROLE_ADMIN.equals(u.getRole()))target=AdminDashboardActivity.class;else session.clear();}else if(u==null||!DBHelper.STATUS_ACTIVE.equals(u.getStatus()))session.clear();Intent i=new Intent(this,target);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);finish();}
}
